#!/bin/sh
# Writes Package.swift for a released version. Run by the Release workflow, which commits the result
# together with the release tag so the checksum always matches the zip attached to that release.
#
# Usage: scripts/write-package-swift.sh <version> <checksum>
set -eu

version="$1"
checksum="$2"

cat > Package.swift <<EOF
// swift-tools-version:5.9
// Generated by scripts/write-package-swift.sh during a release. Do not edit by hand.
import PackageDescription

let package = Package(
    name: "KMPermission",
    platforms: [.iOS(.v15)],
    products: [
        .library(name: "KMPPermissionCore", targets: ["KMPPermissionCore"]),
    ],
    targets: [
        .binaryTarget(
            name: "KMPPermissionCore",
            url: "https://github.com/Ahmadhussain0335/KMPermission/releases/download/v${version}/KMPPermissionCore.xcframework.zip",
            checksum: "${checksum}"
        ),
    ]
)
EOF
